import re

ROW = re.compile(r'^(?P<vmid>\d+)\s+(?P<name>\S(?:.*?\S)?)\s+(?P<file>\[[^\]]+\]\s*.*?\.vmx)\s+(?P<guest>\S+)\s+(?P<ver>vmx-\d+)(?:\s+(?P<ann>\S.*?))?\s*$')
HDR = re.compile(r'^Vmid\s+Name\s+File')
PROMPT = re.compile(r'^\[[^\]]*\][#$]?\s*|^\S+@\S+.*[#$]\s*')

def parse(lines):
    recs = []
    used = []
    skip = []
    cur = None
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if HDR.match(line):
            skip.append(i)
            continue
        m = ROW.match(line)
        if m:
            cur = {'Vmid': m.group('vmid'), 'Name': m.group('name'), 'File': m.group('file'), 'Guest OS': m.group('guest'), 'Version': m.group('ver'), 'Annotation': m.group('ann') or ''}
            recs.append(cur)
            used.append(i)
            continue
        if PROMPT.match(line) and (line.startswith('[') or '@' in line.split()[0]):
            skip.append(i)
            cur = None
            continue
        if cur is not None:
            t = line.strip()
            cur['Annotation'] = (cur['Annotation'] + '\n' + t) if cur['Annotation'] else t
            used.append(i)
    blocks = []
    if recs:
        blocks.append({'name': 'vms', 'kind': 'table', 'lines': used, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
